package com.example.inventory;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.RowMapper;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;

@SpringBootApplication
@RestController
@RequestMapping("/api/v2/inventory")
public class InventoryController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private final ObjectMapper mapper = new ObjectMapper();

    // Flexible search endpoint supporting multiple filter types
    @PostMapping("/search")
    public List<Map<String, Object>> searchInventory(@RequestBody String rawBody) throws Exception {
        JsonNode root = mapper.readTree(rawBody);
        JsonNode filters = root.get("filters");

        StringBuilder query = new StringBuilder("SELECT id, name, quantity, warehouse_id FROM inventory WHERE 1=1");
        List<Object> params = new ArrayList<>();

        if (filters != null && filters.isArray()) {
            for (JsonNode filter : filters) {
                String field = filter.get("field").asText();
                String op = filter.get("op").asText();
                JsonNode value = filter.get("value");

                // Validate field names against whitelist
                if (!isValidField(field)) {
                    throw new IllegalArgumentException("Invalid field: " + field);
                }

                // Type-aware filter construction
                if (op.equals("eq")) {
                    query.append(" AND ").append(field).append(" = ?");
                    params.add(coerceValue(value));
                } else if (op.equals("in")) {
                    // Handle IN clause with dynamic placeholders
                    if (value.isArray()) {
                        query.append(" AND ").append(field).append(" IN (");
                        for (int i = 0; i < value.size(); i++) {
                            if (i > 0) query.append(",");
                            query.append("?");
                            params.add(coerceValue(value.get(i)));
                        }
                        query.append(")");
                    } else {
                        // Type confusion: if 'in' op receives a string instead of array,
                        // treat it as a comma-separated list for backward compat
                        query.append(" AND ").append(field).append(" IN (").append(value.asText()).append(")");
                    }
                } else if (op.equals("like")) {
                    query.append(" AND ").append(field).append(" LIKE ?");
                    params.add("%" + value.asText() + "%");
                } else if (op.equals("range")) {
                    query.append(" AND ").append(field).append(" BETWEEN ? AND ?");
                    params.add(coerceValue(value.get("min")));
                    params.add(coerceValue(value.get("max")));
                }
            }
        }

        // Optional sorting
        JsonNode sort = root.get("sort");
        if (sort != null) {
            String sortField = sort.get("field").asText();
            if (isValidField(sortField)) {
                String dir = sort.has("dir") && sort.get("dir").asText().equalsIgnoreCase("desc") ? "DESC" : "ASC";
                query.append(" ORDER BY ").append(sortField).append(" ").append(dir);
            }
        }

        query.append(" LIMIT 100");

        return jdbcTemplate.queryForList(query.toString(), params.toArray());
    }

    private boolean isValidField(String field) {
        Set<String> allowed = Set.of("id", "name", "quantity", "warehouse_id", "category", "sku");
        return allowed.contains(field.toLowerCase());
    }

    private Object coerceValue(JsonNode node) {
        if (node == null) return null;
        if (node.isInt()) return node.intValue();
        if (node.isLong()) return node.longValue();
        if (node.isDouble()) return node.doubleValue();
        if (node.isBoolean()) return node.booleanValue();
        return node.asText();
    }

    public static void main(String[] args) {
        SpringApplication.run(InventoryController.class, args);
    }
}
